#include <bits/stdc++.h>
using namespace std;

#define int long long

int32_t main() {
	// your code goes here
	int t;
	if(cin>>t){
	    while(t--){
	        int k;
	        cin>>k;
	        
	        int sz = 3*k;
	        vector<int>arr(sz);
	        for(int i=0;i<sz;i++){
	            cin>>arr[i];
	        }
	        
	        sort(arr.begin(),arr.end(),greater<int>());
	        
	        vector<int> psum(sz+1,0);
	        
	        for(int i=0;i<sz;i++){
	            psum[i+1] = psum[i] + arr[i];
	        }
	        int res = 0;
	        
	        for(int i=0;i<=k;i++){
	            int max_j = k-i;
	            int l=0;
	            int r = max_j -1;
	            int best_j = 0;
	            
	            while(l<=r){
	                int m_idx = l +(r-l)/2;
	                
	                int d1 = arr[i+2* m_idx] + arr[i+2*m_idx+1];
	                int d2 = 3*arr[sz-2*i-m_idx-1];
	                
	                if((d1-d2)>=0){
	                    best_j = m_idx+1;
	                    l = m_idx+1;
	                }else{
	                    r =m_idx-1;
	                }
	            }
	            int st=0;
	            if(best_j-2>0){
	                st = best_j-2;
	            }
	            int en = max_j;
	            if(best_j+2<max_j){
	                en = best_j + 2;
	            }
	            
	            for(int j = st;j<=en;j++){
	                int cur = 2* psum[i] + psum[i+2*j]+3*psum[sz-2*i-j];
	                if(cur>res){
	                    res=cur;
	                }
	            }
	        }
	        cout<<res<<"\n";
	    }
	}
	return 0;

}
